/*
* Requires $vars.slackBotToken to be set in Flowise.
*/

const fetch = require('node-fetch');
const token = $vars.slackBotToken;

if (!token) {
    throw new Error('Set $vars.slackBotToken before using this tool.');
}

const limit = Math.min(Math.max(parseInt($message_limit || '20', 10), 1), 200);
const url = new URL('https://slack.com/api/conversations.history');
url.searchParams.set('channel', $channel_id);
url.searchParams.set('limit', limit.toString());

const response = await fetch(url.toString(), {
    method: 'GET',
    headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
    }
});

const data = await response.json();

if (!data.ok) {
    throw new Error('Slack API error: ' + (data.error || 'unknown'));
}

const formatted = data.messages
    .map((msg) => `• ${new Date(msg.ts * 1000).toISOString()} - ${msg.user || 'system'}: ${msg.text}`)
    .join('
');

return formatted || 'No recent messages.';
